"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5902],{62737:e=>{e.exports=JSON.parse('{"functions":[{"name":"frame","desc":"Recomputes this frame\'s deadline. Runs in `Phases.First`.","params":[{"name":"_world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":54,"path":"src/main/server/systems/maze/frame.luau"}}],"properties":[],"types":[],"name":"frame","desc":"Stamps the maze pipeline\'s shared deadline at the top of every frame.\\n\\nThis is the whole of the budget system. Each stage runs until this one\\ninstant, in phase order, so the pipeline cannot exceed `frameMs` however the\\nwork is distributed, and phase order becomes priority order:\\n\\n| Phase | Stage | Why here |\\n|---|---|---|\\n| First | `frame`, `observers` | stamp the deadline, decide intent |\\n| PreUpdate | `hide`, `demolish` | give residency back \u2014 nearly free, and it shrinks the next frame |\\n| Update | `build`, `show` | finish and reveal what is already started |\\n| PostUpdate | `detail`, `load` | decide next frame\'s intent, then start new chunks |\\n| Last | `unload` | trim the far edge |\\n\\nTwo orderings here were arrived at by measurement, not reasoning:\\n\\n**Teardown before everything.** Hiding and detaching cost almost nothing and\\n*reduce* what the engine bills next frame.\\n\\n**Finishing before starting.** `build` outranks `load` because a half-built\\nchunk already pays for its residency without being useful. The margin is a\\nfew percent of frame time and throughput, and only under heavy traversal \u2014\\nthis is the order that holds up under stress, not one the pipeline leans on.\\n\\nEvery stage forces at least one item through when the deadline has passed, so\\nnothing starves. `load` overruns the allowance whenever it runs, because one\\nchunk is a single ~5ms unit \u2014 that is survivable only because it sits behind\\n`build`, so the overrun costs this frame\'s tail instead of the incremental\\nwork. Removing its guarantee to avoid the overrun was tried and left the world\\nunable to rebuild at all under traversal.","tags":["server-system"],"realm":["Server"],"source":{"line":37,"path":"src/main/server/systems/maze/frame.luau"}}')}}]);